<template>
  <div
    class="assistant-chat__card"
    :class="variant !== 'default' ? `assistant-chat__card--${variant}` : ''"
  >
    <slot name="header"></slot>

    <p
      v-if="kicker"
      class="assistant-chat__card-kicker"
      :data-test="`${testId}-label-key`"
    >
      {{ kicker }}
    </p>
    <div v-if="title && badge" class="assistant-chat__card-title">
      <span class="font-semibold">{{ title }}</span>
      <span class="assistant-chat__card-badge">{{ badge }}</span>
    </div>
    <p v-else-if="title" class="font-semibold">{{ title }}</p>
    <p v-if="reason" class="text-sm">{{ reason }}</p>
    <p v-if="meta" class="text-xs text-muted-foreground">
      {{ meta }}
    </p>
    <p
      v-if="hasCurrentValue"
      class="assistant-chat__card-current-value"
      :data-test="`${testId}-current-value`"
    >
      {{ currentLabel || $t('settings_assistant_current_value_label') }}:
      <strong>{{ currentValue }}</strong>
      <template v-if="hasProposedValue">
        <Icon
          icon="mdi:arrow-right"
          width="12"
          height="12"
          class="assistant-chat__card-arrow"
          aria-hidden="true"
        />
        <strong :data-test="`${testId}-proposed-value`">{{ proposedValue }}</strong>
      </template>
    </p>

    <slot></slot>

    <div v-if="$slots.actions" class="assistant-chat__card-actions">
      <slot name="actions"></slot>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { Icon } from '@iconify/vue';

export type AssistantActionCardVariant = 'default' | 'danger' | 'warning';

export default defineComponent({
  name: 'AssistantActionCard',

  components: { Icon },

  props: {
    kicker: {
      type: String,
      default: '',
    },
    title: {
      type: String,
      default: '',
    },
    badge: {
      type: String,
      default: '',
    },
    reason: {
      type: String,
      default: '',
    },
    meta: {
      type: String,
      default: '',
    },
    // null/undefined hides the line; '' or 'false' are real values.
    currentValue: {
      type: String as PropType<string | null>,
      default: null,
    },
    currentLabel: {
      type: String,
      default: '',
    },
    proposedValue: {
      type: String as PropType<string | null>,
      default: null,
    },
    variant: {
      type: String as PropType<AssistantActionCardVariant>,
      default: 'default',
    },
    testId: {
      type: String,
      default: 'settings-assistant',
    },
  },

  computed: {
    hasCurrentValue(): boolean {
      return this.currentValue !== null && this.currentValue !== undefined;
    },
    hasProposedValue(): boolean {
      return this.proposedValue !== null && this.proposedValue !== undefined;
    },
  },
});
</script>

